import{_ as t,o,c as i,a3 as r}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Conventional Priority Architectures (Not Structures)","description":"","frontmatter":{"translationSource":{"title":"常规优先级架构（不是结构）","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=8Aa94f8lDPwQd8yIT0MD2Q","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/conventional-priority-architectures"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/conventional-priority-architectures"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/conventional-priority-architectures"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/conventional-priority-architectures"}]]},"headers":[],"relativePath":"conventional-priority-architectures.md","filePath":"logistics/src/page-8Aa94f8lDPwQd8yIT0MD2Q.md"}'),a={name:"conventional-priority-architectures.md"};function s(n,e,l,p,c,d){return o(),i("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><h1 id="conventional-priority-architectures-not-structures" tabindex="-1">Conventional Priority Architectures (Not Structures) <a class="header-anchor" href="#conventional-priority-architectures-not-structures" aria-label="Permalink to &quot;Conventional Priority Architectures (Not Structures)&quot;">​</a></h1><blockquote><p>Source page ID: <code>8Aa94f8lDPwQd8yIT0MD2Q</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=8Aa94f8lDPwQd8yIT0MD2Q" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span id="source-block-qeUyFTFv540Pj8s5z2kQzC"></span></p><h2 id="conventional-priorities" tabindex="-1">Conventional Priorities <a class="header-anchor" href="#conventional-priorities" aria-label="Permalink to &quot;Conventional Priorities&quot;">​</a></h2><p>Priorities at different locations can be combined to create more priority levels. Multilevel priority logistics structures can also do this. Conventional priority methods can usually replace one another.</p><p><span id="source-block-mlwukQHgPBO54VVp05zSz0"></span></p><h3 id="depot-priorities" tabindex="-1">Depot Priorities <a class="header-anchor" href="#depot-priorities" aria-label="Permalink to &quot;Depot Priorities&quot;">​</a></h3><p><span id="source-block-NtWSrl6BOEbKXLVaBXjCTS"></span></p><h4 id="oversupply-with-empty-storage" tabindex="-1"><strong>Oversupply with Empty Storage</strong> <a class="header-anchor" href="#oversupply-with-empty-storage" aria-label="Permalink to &quot;**Oversupply with Empty Storage**&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e107d022f2df1611.q90-31352a454e52364d.webp" alt="Conventional Priority Architectures (Not Structures)"></p><p>Oversupply with empty storage uses more Depot Unloaders than usual on the high-priority route so that it withdraws more items from the depot.</p><p>Advantages: simple structure; modifications do not require changing the line before it enters the depot, making modules easier to add.</p><p>Disadvantages: the existence and instability of Unloader priorities prevent any guarantee that Unloaders on the high-priority route work normally; they may never output anything. Excessive oversupply has pronounced diminishing returns, and space for Unloaders runs out. Too many high-priority Unloaders also make routing troublesome.</p><p><a href="/endfield-skydoc/1-5-automatic-maximum-gross-production">1.5 Automatic Maximum Gross Production</a></p><p><span id="source-block-PU8JOqEVFjZT88TUdCy6qR"></span></p><h4 id="full-storage-oscillation" tabindex="-1"><strong>Full-Storage Oscillation</strong> <a class="header-anchor" href="#full-storage-oscillation" aria-label="Permalink to &quot;**Full-Storage Oscillation**&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d77a1b82ac561f2c.q90-8a37714e0e2ebab2.webp" alt="Conventional Priority Architectures (Not Structures)"></p><p>Full-storage oscillation uses full-storage detection + a timer + a latching circuit breaker to provide low-priority output. Only after storage fills does it produce high output (a high level) for a period (set by the timer), without emptying storage; otherwise the low-priority route outputs nothing (a low level). This ensures that the high-priority route can always output items.</p><p>Advantages: a uniform, expandable structure; no need to account for unstable Unloader priorities.</p><p>Disadvantages: adding modules also requires adding low-priority full-storage-oscillation structures, which is inconvenient. Low-priority structures cannot be assigned different priorities among themselves. The design depends on Loader priorities. Before each full-storage detection, there is a short period of reduced production due to full storage, which must be solved by oversupplying the depot input.</p><p><a href="/endfield-skydoc/full-storage-oscillation-plan">1.6 Automatic Maximum Gross Production</a></p><p><span id="source-block-EAjCnqNEuX5TFnRRMqCyTj"></span></p><h4 id="empty–full-storage-oscillation" tabindex="-1">Empty–Full Storage Oscillation <a class="header-anchor" href="#empty–full-storage-oscillation" aria-label="Permalink to &quot;Empty–Full Storage Oscillation&quot;">​</a></h4><p>A special form of full-storage oscillation, combining full-storage detection + empty-storage detection + a latching circuit breaker. Instead of high output lasting for a set time after storage fills, this oscillation continues until storage empties, giving a longer cycle than full-storage oscillation.</p><p>Advantages over full-storage oscillation: detection can use fewer logistics components; production loss from full storage is smaller and negligible.</p><p>Disadvantages compared with full-storage oscillation: empty-storage detection reintroduces the need to account for unstable Unloader priorities.</p><p>See the pictures posted by 赫 in the Technology Development Bureau group&#39;s photo album.</p><p><span id="source-block-wpW334zm3uFiqbaymwtwu8"></span></p><h3 id="priorities-before-the-depot" tabindex="-1">Priorities before the Depot <a class="header-anchor" href="#priorities-before-the-depot" aria-label="Permalink to &quot;Priorities before the Depot&quot;">​</a></h3><p><span id="source-block-zCQhpg8Az6d7dBtqlv3ycQ"></span></p><h4 id="full-storage-overflow" tabindex="-1"><strong>Full-Storage Overflow</strong> <a class="header-anchor" href="#full-storage-overflow" aria-label="Permalink to &quot;**Full-Storage Overflow**&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d845857d448bfcb6.q90-4507487e69954545.webp" alt="Conventional Priority Architectures (Not Structures)"></p><p>Full-storage overflow assigns priorities to products before they enter the depot, avoiding unstable depot-related priorities at the cost of having to build the priority arrangements before storage.</p><p>Advantages: all priorities used are stable, so instability need not be considered. Upper and lower limits can be farther apart, with almost no diminishing returns. High-priority modules are easy to add.</p><p>Disadvantages: enormous footprint, since every production unit needs its own overflow module; module division and compression before the depot need to be studied anew.</p><p><a href="/endfield-skydoc/full-storage-overflow-compatible-with-1-5-automatic-gross-production">Full-Storage Overflow Plan Compatible with 1.5 Automatic Gross Production</a></p><p><span class="mark-grey">#言 (no one has checked this conclusion yet)<br> It should be noted that, if Loader priorities are allowed, not every production unit needs an overflow module—production units not connected to an overflow module use a deposit route whose intake capacity exceeds their production rate and whose priority is higher (for example, Cuprium refining uses two belts to connect two Depot Loaders with higher priority than the Loader of the Cuprium refining that is connected to the overflow module), while production units connected to an overflow module use a lower-priority deposit route.<br> Principle in brief: from kokobird&#39;s account of deposit competition in</span><a href="/endfield-skydoc/2-6-empty-storage-full-storage-we-need-more-oversupply">2.6 Empty Storage? Full Storage? We Need More Oversupply!</a><span class="mark-grey">, we know that when the withdrawal waveform (the time function of withdrawal) at some moment falls below the deposit waveform (the time function of deposit) that should be given priority, the production unit that should deposit first will wrongly pile up products; but with “a deposit route whose intake capacity exceeds the production rate and whose priority is higher”, those piled-up products can be deposited once the withdrawal waveform rises above the deposit waveform—as long as the fluctuation does not overrun that production unit&#39;s buffer, its products are guaranteed to be fully deposited.</span></p><p><span id="source-block-NdoI0MM1aeyFeix9zEe3CQ"></span></p><h4 id="empty-storage-overflow" tabindex="-1">Empty-Storage Overflow <a class="header-anchor" href="#empty-storage-overflow" aria-label="Permalink to &quot;Empty-Storage Overflow&quot;">​</a></h4><p>Empty-storage overflow is a variant of full-storage overflow. Xiranite can be given priority for returning to storage relatively simply through a reaction tank, but items such as Cuprium are less convenient to prioritize this way. Instead, exchange the roles of products returned to storage and products kept out of storage.</p><p>Advantages over full-storage overflow: another implementation approach that, in some cases, simplifies priority implementation for particular items.</p><p>Disadvantages compared with full-storage overflow: high-priority paths cannot pass through the depot, making modules harder to add.</p><p><span id="source-block-KUQGdcq4cAbeg5ZiVm830v"></span></p><h3 id="priorities-after-the-depot" tabindex="-1">Priorities after the Depot <a class="header-anchor" href="#priorities-after-the-depot" aria-label="Permalink to &quot;Priorities after the Depot&quot;">​</a></h3><p><span id="source-block-N7wpQpcB2PvmZfp0tGr0Nx"></span></p><h4 id="simple-overflow" tabindex="-1">Simple Overflow <a class="header-anchor" href="#simple-overflow" aria-label="Permalink to &quot;Simple Overflow&quot;">​</a></h4><p>Simple overflow creates priorities after the depot. Give every Depot Unloader its own priority logistics structure and provide enough Unloaders. Input materials may have either empty or full storage, although normal utilization is achieved only with empty storage.</p><p>Advantages: strict priorities, without accounting for unstable depot priorities.</p><p>Disadvantages: large footprint; building priorities for every Unloader is inefficient.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6495d4ded2b49faa.jpeg" alt="Conventional Priority Architectures (Not Structures)"></p><p><span id="source-block-BNBg7dgMA5g42ZnlcO4cEt"></span></p><h4 id="constant-flow-overflow" tabindex="-1">Constant-Flow Overflow <a class="header-anchor" href="#constant-flow-overflow" aria-label="Permalink to &quot;Constant-Flow Overflow&quot;">​</a></h4><p>[Too simple to need a diagram]</p><p>Constant-flow overflow is a variant of simple overflow that adds a constraint on the number of Unloaders, keeping that number fixed.</p><p>Advantages over simple overflow: a more fixed layout.</p><p>Disadvantages compared with simple overflow: more constraints and less flexibility.</p><p><span id="source-block-g2syXYc9TTPD3TDaELvEZP"></span></p><h2 id="special-priority-relationships" tabindex="-1">Special Priority Relationships <a class="header-anchor" href="#special-priority-relationships" aria-label="Permalink to &quot;Special Priority Relationships&quot;">​</a></h2><p><span id="source-block-2KOpd4h0lpe9FzNsZ8Hbqf"></span></p><h3 id="input–product-priority-relationships" tabindex="-1">Input–Product Priority Relationships <a class="header-anchor" href="#input–product-priority-relationships" aria-label="Permalink to &quot;Input–Product Priority Relationships&quot;">​</a></h3><p><span id="source-block-p7XbL4osQRZseYq4UXGFDn"></span></p><h4 id="product-empty-storage-oscillation" tabindex="-1">Product Empty-Storage Oscillation <a class="header-anchor" href="#product-empty-storage-oscillation" aria-label="Permalink to &quot;Product Empty-Storage Oscillation&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c275fe01f08dcc19.q90-f85b415e5997815e.webp" alt="Conventional Priority Architectures (Not Structures)"></p><p>Product empty-storage oscillation aims to keep a particular item from remaining depleted. Here “empty storage” means the product stock is empty, yet not entirely so. Essentially, retaining input materials takes priority over converting them into products.</p><p>Advantages: ensures the target does not remain out of stock; simple structure.</p><p>Disadvantages: its distinctive priority mechanism does not suit the situations addressed by other methods. Products frequently reach zero, so further processing may be unable to obtain enough items. Empty-storage detection is necessary, giving a somewhat larger footprint.</p><p><a href="https://www.bilibili.com/video/BV1vxJq6UEao/?" target="_blank" rel="noreferrer">Automatic Restocking and Ingredient-Preparation Line</a></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-48f858c33534d036.jpeg" alt="Conventional Priority Architectures (Not Structures)"></p><p><span id="source-block-9KPGt2ZWb52zRgnQaxurpo"></span></p><h4 id="input-empty-storage-oscillation" tabindex="-1">Input Empty-Storage Oscillation <a class="header-anchor" href="#input-empty-storage-oscillation" aria-label="Permalink to &quot;Input Empty-Storage Oscillation&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-dc1a860e44d05fa0.q90-9ad4ffccfdd392fc.webp" alt="Conventional Priority Architectures (Not Structures)"></p><p>This resembles product empty-storage oscillation, except that the input stock empties. The principle needs a little explanation: when inputs are abundant, withdrawal from storage exceeds the return flow, so the excess is processed. When inputs are insufficient, they always take the high-priority route and are not processed. Returning them by belt prevents everything from being withdrawn immediately upon re-entering storage, ensuring there are times when the stock is nonzero and available for use.</p><p>Advantages: simple structure; no storage-level detection; few Unloaders needed.</p><p>Disadvantages: a small oscillation range—at most 5 items per Unloader in each 10s cycle. Increasing the range requires many more Unloaders.</p><p><span id="source-block-2xpIgEALoqCpplNqo7yTn8"></span></p><h4 id="fixed-production-through-rate-limiting" tabindex="-1">Fixed Production through Rate Limiting <a class="header-anchor" href="#fixed-production-through-rate-limiting" aria-label="Permalink to &quot;Fixed Production through Rate Limiting&quot;">​</a></h4><p>Calculate the product&#39;s average consumption rate, then limit production to approximately that rate. Essentially, assume ample input and produce slightly faster than consumption, simulating a high-priority route.</p><p>Advantages: fast startup; near steady state as soon as it starts.</p><p>Disadvantages: it does not implement normal priorities and therefore cannot be used for automatic production balancing.</p><p><span id="source-block-hvZ0AGS2NcA9LkaMs32paQ"></span></p><h3 id="preferential-consumption" tabindex="-1">Preferential Consumption <a class="header-anchor" href="#preferential-consumption" aria-label="Permalink to &quot;Preferential Consumption&quot;">​</a></h3><p><span id="source-block-2AsLx49xwckIpYbW86vESE"></span></p><h4 id="preferentially-consuming-one-battery-type-for-power-generation" tabindex="-1">Preferentially Consuming One Battery Type for Power Generation <a class="header-anchor" href="#preferentially-consuming-one-battery-type-for-power-generation" aria-label="Permalink to &quot;Preferentially Consuming One Battery Type for Power Generation&quot;">​</a></h4><p>Content to be added. One suggestion is that “omitting full-storage detection for the high-consumption item naturally enables automatic switching”; theoretical support is currently lacking.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a4abd54bf8334190.q90-58fa5d62cc05ad30.webp" alt="Conventional Priority Architectures (Not Structures)"></p></div>',1)])])}const g=t(a,[["render",s]]);export{h as __pageData,g as default};
